cd /workspace && sleep 4 && echo "--- re-GET after background sync should be FRESH (stock decremented: 11/29/0/53/6) ---" && curl -s http://localhost:3111/ -o /tmp/page3.html && node -e '
const fs=require("fs");
const h=fs.readFileSync("/tmp/page3.html","utf8");
const rows=[...h.matchAll(/<tr>\s*<td[^>]*>([^<]+)<\/td>\s*<td[^>]*>([^<]+)<\/td>\s*<td[^>]*>\$([^<]+)<\/td>\s*<td[^>]*>([^<]+)<\/td>\s*<td[^>]*>[\s\S]*?<\/td>\s*<\/tr>/g)];
for(const r of rows){ console.log(r[2].padEnd(12), "price=$"+r[3], "stock="+r[4]); }
