cd /workspace && node -e '
const fs=require("fs");
const h=fs.readFileSync("/tmp/page3.html","utf8");
const tbody=h.slice(h.indexOf("<tbody>"), h.indexOf("</tbody>"));
const trs=[...tbody.matchAll(/<tr>([\s\S]*?)<\/tr>/g)].map(m=>m[1]);
for(const tr of trs){
  const cells=[...tr.matchAll(/<td[^>]*>([\s\S]*?)<\/td>/g)].map(m=>m[1].replace(/<[^>]+>/g,"").trim());
  console.log(cells[1].padEnd(12), "price=$"+cells[2], "stock="+cells[3], "status="+cells[4]);
}
'
